import type { ChartRenderFn } from "../renderers/genericChartRenderer";

export const renderPie: ChartRenderFn = (container, data, params, d3, containerWidth) => {
  container.innerHTML = "";
  const axisLabel = params.axisLabel ?? "";
  const props = params;

  const values = Object.fromEntries(
    Object.entries(data).map(([k, row]) => [k, row[axisLabel]]),
  );

  const width = containerWidth || 260;
  const height = 220;

  const entries = Object.entries(values);
  const colorProp = props?.color ?? props?.colors;
  const entryColors = entries.map(([label], index) => {
    if (typeof colorProp === "string") {
      return colorProp;
    }

    if (Array.isArray(colorProp) && colorProp.length > 0) {
      return colorProp[index % colorProp.length];
    }

    if (colorProp && typeof colorProp === "object" && !Array.isArray(colorProp)) {
      return colorProp[label] ?? d3.schemeTableau10[index % d3.schemeTableau10.length];
    }

    return d3.schemeTableau10[index % d3.schemeTableau10.length];
  });

  const root = d3
    .select(container)
    .style("width", "100%")
    .style("overflow", "hidden")
    .style("display", "flex")
    .style("flex-direction", "column")
    .style("gap", "6px");

  const legendRow = root
    .append("div")
    .style("display", "flex")
    .style("justify-content", "center")
    .style("align-items", "center")
    .style("gap", "16px")
    .style("padding", "0 6px")
    .style("flex-wrap", "wrap");

  const legendItems = legendRow
    .append("div")
    .style("display", "flex")
    .style("gap", "14px")
    .style("flex-wrap", "wrap")
    .style("align-items", "center")
    .style("font-family", "Inter, sans-serif")
    .style("font-size", "16px")
    .style("font-weight", "500");

  entries.forEach(([label], index) => {
    const item = legendItems
      .append("div")
      .style("display", "flex")
      .style("align-items", "center")
      .style("gap", "6px");
    item
      .append("span")
      .style("width", "14px")
      .style("height", "14px")
      .style("border-radius", "2px")
      .style("background-color", entryColors[index]);
    item.append("span").text(label);
  });

  const svg = root
    .append("svg")
    .style("display", "block")
    .style("margin", "0 auto")
    .attr("width", width)
    .attr("height", height);

  root
    .append("div")
    .style("margin-top", "4px")
    .style("text-align", "center")
    .style("font-size", "16px")
    .style("font-family", "Inter, sans-serif")
    .style("font-weight", "500")
    .text(`${axisLabel} (${props?.unit ?? ""})`);

  if (entries.length === 0) return;

  const margin = 10;
  const innerWidth = width - margin * 2;
  const innerHeight = height - margin * 2;

  const radius = Math.min(innerWidth, innerHeight) / 2;

  const g = svg
    .append("g")
    .attr("transform", `translate(${width / 2}, ${height / 2 + 6})`);

  const pie = d3
    .pie()
    .value(([, v]) => v)
    .sort(null);

  const arc = d3
    .arc()
    .innerRadius(radius * 0.45)
    .outerRadius(radius);

  const arcs = pie(entries);

  g.selectAll("path")
    .data(arcs)
    .enter()
    .append("path")
    .attr("d", arc)
    .attr("fill", (_d, i) => entryColors[i])
    .attr("stroke", "#fff")
    .attr("stroke-width", 1.2);

  g.selectAll("text.slice-label")
    .data(arcs)
    .enter()
    .append("text")
    .attr("class", "slice-label")
    .attr("transform", (d) => `translate(${arc.centroid(d)})`)
    .attr("text-anchor", "middle")
    .style("font-family", "Inter, sans-serif")
    .style("font-size", "15px")
    .style("fill", "#ffffff")
    .text((d) => d.data[1].toFixed(2));
};
